async function mediaData(file:File){if(file.type.startsWith("image/")){let bmp:ImageBitmap;try{bmp=await createImageBitmap(file)}catch{throw new Error("Coba masukkan ulang foto referensinya atau video referensinya, lalu coba lagi.")}try{const scale=Math.min(1,1600/Math.max(bmp.width,bmp.height));const c=document.createElement("canvas");c.width=Math.round(bmp.width*scale);c.height=Math.round(bmp.height*scale);const ctx=c.getContext("2d");if(!ctx)throw new Error("Tidak dapat memproses gambar.");ctx.drawImage(bmp,0,0,c.width,c.height);const blob=await new Promise<Blob|null>(resolve=>c.toBlob(resolve,"image/jpeg",0.78));if(!blob)throw new Error("Gagal mengompres gambar.");if(blob.size>0.8*1024*1024)throw new Error("Gambar terlalu besar. Pilih gambar lain.");return await dataUrl(new File([blob],"reference.jpg",{type:"image/jpeg"}))}finally{bmp.close()}}if(file.size>3*1024*1024)throw new Error("File video/audio terlalu besar untuk dikirim dari browser. Maksimal sekitar 3 MB per file.");return await dataUrl(file)}
async function trimAudioTo30Seconds(file:File){
 const Ctor=(window as any).AudioContext||(window as any).webkitAudioContext;
 if(!Ctor)throw new Error("Browser tidak mendukung pemrosesan audio. Gunakan Chrome terbaru.");
 const ctx=new Ctor();
 try{
  const decoded=await ctx.decodeAudioData(await file.arrayBuffer());
  if(decoded.duration<=30)return file;
  const channels=decoded.numberOfChannels,frames=Math.floor(decoded.sampleRate*30),block=channels*2,size=frames*block;
  const buffer=new ArrayBuffer(44+size),v=new DataView(buffer);
  const put=(o:number,s:string)=>{for(let i=0;i<s.length;i++)v.setUint8(o+i,s.charCodeAt(i));};
  put(0,"RIFF");v.setUint32(4,36+size,true);put(8,"WAVE");put(12,"fmt ");v.setUint32(16,16,true);v.setUint16(20,1,true);v.setUint16(22,channels,true);v.setUint32(24,decoded.sampleRate,true);v.setUint32(28,decoded.sampleRate*block,true);v.setUint16(32,block,true);v.setUint16(34,16,true);put(36,"data");v.setUint32(40,size,true);
  const data=Array.from({length:channels},(_,i)=>decoded.getChannelData(i));let o=44;
  for(let i=0;i<frames;i++)for(let ch=0;ch<channels;ch++){const x=Math.max(-1,Math.min(1,data[ch][i]));v.setInt16(o,x<0?x*32768:x*32767,true);o+=2;}
  return new File([buffer],file.name.replace(/\.[^.]+$/,"")+"_30s.wav",{type:"audio/wav"});
 }finally{await ctx.close().catch(()=>{});}
}
