async function posbotRequest(body:any) {
 const r=await fetch("/api/posbot",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(body)});
 const d=await r.json().catch(()=>({error:"Respons PosBot tidak valid."}));
 if(!r.ok||d.ok===false)throw new Error(d.error||"Permintaan PosBot gagal ("+r.status+").");
 return d;
}
async function uploadPosbotFile(file:File,kind:"image"|"video"|"audio") {
 const signed=await posbotRequest({resource:"sign-upload",kind,name:file.name});
 const url=process.env.NEXT_PUBLIC_SUPABASE_URL,anon=process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY;
 if(!url||!anon)throw new Error("Konfigurasi Supabase publik belum lengkap.");
 const client=createClient(url,anon);
 const {error}=await client.storage.from("posbot-inputs").uploadToSignedUrl(signed.path,signed.token,file,{contentType:file.type||"application/octet-stream"});
 if(error)throw new Error("Upload "+file.name+" gagal: "+error.message);
 const complete=await posbotRequest({resource:"complete-upload",path:signed.path});
 return {kind,url:complete.url};
}
