async function videoGenerate(){setBusy(true);flash("");try{if(usingPosbotVideo){await generatePosbotVideo();return;}const files=media;let payload:any={};if(mode==="motion"){if(!files[0])throw new Error("Pilih video referensi gerakan terlebih dahulu.");if(motionTarget==="male"&&!motionMale)throw new Error("Unggah foto Male terlebih dahulu.");if(motionTarget==="female"&&!motionFemale)throw new Error("Unggah foto Female terlebih dahulu.");if(motionTarget==="both")throw new Error("Mode dua orang belum bisa dijalankan: konektor Nexa R2V saat ini hanya menerima 1 video + maksimal 1 foto referensi. Dua foto terpisah belum didukung, jadi KAZAMA tidak akan menggabungkan atau mengirim foto secara keliru.");const identity=motionTarget==="male"?motionMale:motionFemale;payload.media=[await mediaData(files[0]),await mediaData(identity!)];await submitJob("r2v",motionPrompt(motionTarget),{...payload,displayPrompt:"Motion Control · "+(motionTarget==="male"?"Male only":"Female only")+" · Auto prompt"});return;}if(mode==="sfv"||mode==="i2v"){const count=mode==="sfv"?1:3;if(files.length<(mode==="sfv"?1:1)||files.length>count)throw new Error(mode==="sfv"?"Start frame membutuhkan tepat 1 gambar.":"Image-to-Video membutuhkan 1–3 gambar.");payload.media=await Promise.all(files.map(mediaData));}if(mode==="r2v"||mode==="extend"){if(!files[0])throw new Error("Pilih satu video referensi.");payload.media=[await mediaData(files[0])];if(mode==="r2v"&&optImage)payload.media.push(await mediaData(optImage));}await submitJob(mode,prompt,payload)}catch(e){flash(e instanceof Error?e.message:String(e),true)}finally{setBusy(false)}}
