{tab==="voice"&&<><div className="pagehead"><div className="kicker">ELEVENLABS VOICE GENERATOR</div><h1>Voice <em>Generator</em></h1><p>Natural speech with voice selection, language, speed, stability, similarity, and style controls.</p></div><div className="workgrid"><section className="panel formpanel"><div className="field"><label>TEXT · MAX 5,000 CHARACTERS</label><textarea value={voiceText} onChange={e=>setVoiceText(e.target.value)} maxLength={5000} placeholder="Masukkan naskah yang akan diucapkan..."/></div><div className="fieldgrid"><div className="field"><label>VOICE</label><select value={voiceId} onChange={e=>setVoiceId(e.target.value)}>{voices.map(v=><option key={v.voice_id} value={v.voice_id}>{v.name||v.voice_id}</option>)}{!voices.length&&VOICES.map(v=><option key={v}>{v}</option>)}</select></div><div className="field"><label>LANGUAGE</label><select value={language} onChange={e=>setLanguage(e.target.value)}><option value="id-ID">Indonesian</option><option value="en-US">English US</option><option value="en-GB">English UK</option><option value="ja-JP">Japanese</option><option value="ko-KR">Korean</option></select></div><div className="field"><label>SPEED · 0.5–2</label><input type="number" min="0.5" max="2" step="0.1" value={voiceSpeed} onChange={e=>setVoiceSpeed(e.target.value)}/></div></div><Range label="STABILITY" value={stability} set={setStability}/><Range label="SIMILARITY BOOST" value={similarity} set={setSimilarity}/><Range label="STYLE" value={style} set={setStyle}/><div className="costline"><span>Voice generation <b>200 Credit</b></span><span>Endpoint <b>/voice</b></span></div><button className="primary full" disabled={busy||!configured} onClick={makeVoice}>{busy?<LoaderCircle className="spin"/>:<Mic size={17}/>} Generate Voice</button></section><OutputBox resultUrl={resultUrl} resultKind="audio" jobs={jobs} lastTask={lastTask} onShowHistory={()=>setTab("history")}/></div></>}
